#!/usr/bin/env node
// Offline check of the generated site (repository root, generated by scripts/build-site.mjs):
//  - every internal href/src resolves to an existing file (and #anchor exists if given)
//  - every generated page has a <title>, an <h1>, the shared navigation, stylesheet and script
//  - the committed pages match what the templates + data would generate (no stale site)
//  - the data files the pages depend on exist
// archive/ holds the prior-session site trees: link check only, no template check.
//
// External links are listed (not fetched) so a reviewer can check them by hand.
import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const here = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(here, "..");

const SKIP = new Set(["node_modules", "scripts", "templates", "data", "tools", ".github", ".git"]);
function walk(dir) {
  return readdirSync(dir).flatMap((f) => {
    if (f.startsWith(".") || SKIP.has(f)) return [];
    const p = join(dir, f);
    return statSync(p).isDirectory() ? walk(p) : p.endsWith(".html") ? [p] : [];
  });
}

const errors = [];
const external = new Set();
const idsCache = new Map();
const idsOf = (file) => {
  if (!idsCache.has(file)) {
    const html = readFileSync(file, "utf8");
    idsCache.set(file, new Set([...html.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1])));
  }
  return idsCache.get(file);
};

for (const required of ["data/snapshot.json", "data/sources.json", "assets/app.js", "assets/chart.js", "assets/style.css"]) {
  if (!existsSync(join(ROOT, required))) errors.push(`missing required file: ${required}`);
}

const pages = walk(ROOT);
for (const file of pages) {
  const html = readFileSync(file, "utf8");
  const rel = file.slice(ROOT.length + 1);
  // dash/, docs/, audit/ and archive/ are independent pages / suites / preserved trees: link-checked only.
  const independent = rel.startsWith("archive/") || rel.startsWith("dash/") || rel.startsWith("docs/") || rel.startsWith("audit/");

  if (!independent) {
    if (!/<title>[^<]+<\/title>/.test(html)) errors.push(`${rel}: missing <title>`);
    if (!/<h1[ >]/.test(html)) errors.push(`${rel}: missing <h1>`);
    if (!html.includes('class="nav-inner"')) errors.push(`${rel}: missing shared navigation`);
    if (!/href="[^"]*assets\/style\.css"/.test(html)) errors.push(`${rel}: missing stylesheet link`);
    if (!/src="[^"]*assets\/app\.js"/.test(html)) errors.push(`${rel}: missing app.js`);
    if (/\{\{[A-Z_]+/.test(html)) errors.push(`${rel}: unresolved template placeholder`);
  }

  // JavaScript fragments inside inline <script> blocks contain href/src string
  // concatenations that are not real links — strip script/style blocks first.
  const scanText = html.replace(/<script\b[\s\S]*?<\/script>|<style\b[\s\S]*?<\/style>/gi, " ");
  for (const m of scanText.matchAll(/\b(href|src)="([^"]*)"/g)) {
    const raw = m[2];
    if (raw === "" || raw.startsWith("mailto:") || raw.startsWith("data:") || raw.startsWith("#")) continue;
    if (raw.includes("${")) continue;
    if (/^https?:\/\//.test(raw)) { external.add(raw); continue; }
    const [withQuery, hash] = raw.split("#");
    const pathPart = withQuery.split("?")[0];
    if (pathPart === "") continue;
    const target = resolve(dirname(file), pathPart);
    if (!target.startsWith(ROOT)) { errors.push(`${rel}: link escapes site: ${raw}`); continue; }
    if (!existsSync(target)) { errors.push(`${rel}: broken link ${raw}`); continue; }
    if (hash && target.endsWith(".html") && !idsOf(target).has(hash)) errors.push(`${rel}: missing anchor ${raw}`);
  }
}

// The committed site must match the templates + data (CI staleness gate).
try {
  execFileSync(process.execPath, [join(here, "build-site.mjs"), "--check"], { stdio: "pipe" });
} catch (e) {
  errors.push(`generated site is stale: ${(e.stdout || "").toString().trim() || (e.stderr || "").toString().trim()}`);
}

console.log(`Checked ${pages.length} pages.`);
console.log(`External links (not fetched, listed for review): ${external.size}`);
if (process.argv.includes("--list-external")) {
  for (const u of [...external].sort()) console.log("  " + u);
}
if (errors.length) {
  console.error(`\n${errors.length} problem(s):`);
  for (const e of errors) console.error(" - " + e);
  process.exit(1);
}
console.log("No broken internal links.");
